PTX_SOURCE = r'''
.version 7.1
.target sm_80
.address_size 64

// Kernel: argmax over dimension provided at runtime (only dim=1 is needed for the reference)
// Input:  fp16 tensor (B, D1, D2)
// Output: int64 indices tensor with the reduced dimension removed
.visible .entry argmax_kernel(
    .param .u64 out_ptr,      // pointer to output (int64)
    .param .u64 in_ptr,       // pointer to input  (fp16)
    .param .u32 dim,          // reduced dimension (ignored, we assume dim==1)
    .param .u32 batch,        // B
    .param .u32 dim1,         // D1
    .param .u32 dim2          // D2
)
{
    // ----------------------------------------------------------------------
    // Thread indexing
    // ----------------------------------------------------------------------
    .reg .pred  %p0, %p1, %p2;
    .reg .u32   %tid_x, %block_idx_x, %block_dim_x, %global_idx;
    .reg .u32   %b, %d2;               // batch index, dim2 index (output coordinates)
    .reg .u64   %out, %inp;            // base pointers
    .reg .u64   %addr;                 // element address
    .reg .f16   %val, %maxval;         // values
    .reg .s32   %c, %maxidx, %tmp_idx; // loop counter & best index
    .reg .u64   %out_addr, %maxidx_u64;

    // thread id within block and block id
    mov.u32 %tid_x,      %tid.x;
    mov.u32 %block_idx_x,%ctaid.x;
    mov.u32 %block_dim_x,%ntid.x;

    // linear global thread id
    mad.lo.u32 %global_idx, %block_idx_x, %block_dim_x, %tid_x;

    // ----------------------------------------------------------------------
    // Load kernel parameters
    // ----------------------------------------------------------------------
    ld.param.u64 %out, [out_ptr];
    ld.param.u64 %inp, [in_ptr];
    ld.param.u32 %batch, [batch];
    ld.param.u32 %dim1, [dim1];
    ld.param.u32 %dim2, [dim2];

    // ----------------------------------------------------------------------
    // Compute output coordinates for dim==1 (output shape: (B, D2))
    // ----------------------------------------------------------------------
    // b = global_idx / dim2
    // d2 = global_idx % dim2
    div.u32 %b, %global_idx, %dim2;
    mul.lo.u32 %tmp_idx, %b, %dim2;
    sub.u32 %d2, %global_idx, %tmp_idx;

    // ----------------------------------------------------------------------
    // Load first element of the reduction to initialise max
    // ----------------------------------------------------------------------
    // address = ((b * dim1 + 0) * dim2 + d2) * sizeof(half)
    mul.lo.u32 %tmp_idx, %b, %dim1;                 // b * dim1
    mul.lo.u64 %addr, %tmp_idx, %dim2;              // (b*dim1) * dim2
    add.u64 %addr, %addr, %d2;                      // + d2
    mul.lo.u64 %addr, %addr, 2;                     // *2 bytes (half)
    add.u64 %addr, %inp, %addr;                     // base + offset
    ld.global.f16 %maxval, [%addr];
    mov.s32 %maxidx, 0;

    // ----------------------------------------------------------------------
    // Loop over the reduction dimension (dim1)
    // ----------------------------------------------------------------------
    mov.u32 %c, 1;                      // start from 1, 0 already loaded

LOOP_START:
    setp.ge.u32 %p0, %c, %dim1;        // if c >= dim1 exit
    @%p0 bra LOOP_END;

    // address = ((b * dim1 + c) * dim2 + d2) * 2
    mul.lo.u32 %tmp_idx, %b, %dim1;    // b * dim1
    add.u32 %tmp_idx, %tmp_idx, %c;    // b*dim1 + c
    mul.lo.u64 %addr, %tmp_idx, %dim2;
    add.u64 %addr, %addr, %d2;
    mul.lo.u64 %addr, %addr, 2;
    add.u64 %addr, %inp, %addr;

    ld.global.f16 %val, [%addr];

    // if (val > maxval) update
    setp.gt.f16 %p1, %val, %maxval;
    @%p1 {
        mov.f16 %maxval, %val;
        mov.s32 %maxidx, %c;
    }

    add.u32 %c, %c, 1;
    bra LOOP_START;

LOOP_END:
    // ----------------------------------------------------------------------
    // Write result (int64) to output
    // ----------------------------------------------------------------------
    // out_addr = out + global_idx * 8
    mul.lo.u64 %out_addr, %global_idx, 8;
    add.u64 %out_addr, %out, %out_addr;

    cvt.u64.u32 %maxidx_u64, %maxidx;
    st.global.u64 [%out_addr], %maxidx_u64;

    ret;
}
'''

import torch
import torch.nn as nn

class ModelNew(nn.Module):
    def __init__(self, dim: int):
        super().__init__()
        self.dim = dim
        # load PTX module
        self.module = ptx_load(PTX_SOURCE)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # x is fp16 CUDA tensor with shape (B, D1, D2)
        B, D1, D2 = x.shape
        # determine output shape after argmax over self.dim
        if self.dim == 0:
            out_shape = (D1, D2)
        elif self.dim == 1:
            out_shape = (B, D2)
        elif self.dim == 2:
            out_shape = (B, D1)
        else:
            raise RuntimeError("Invalid dim")
        # allocate output tensor (int64)
        out = torch.empty(out_shape, dtype=torch.int64, device=x.device)

        # launch configuration: one thread per output element
        total = out.numel()
        block = 256
        grid_x = (total + block - 1) // block
        grid = (grid_x, 1, 1)

        # kernel arguments: pointers and sizes
        args = [
            out.data_ptr(),
            x.data_ptr(),
            self.dim,          # reduced dimension (int32)
            B,
            D1,
            D2
        ]

        ptx_launch(self.module, "argmax_kernel", grid, (block, 1, 1), args)
        return out
